# ABOUTME: Main Chalk module - loads all parser components
# ABOUTME: Entry point for using Chalk parser library
use 5.42.0;
use experimental qw(class builtin keyword_any keyword_all);
use utf8;
use open qw(:std :utf8);

# Load all Chalk modules
use Chalk::Base;
use Chalk::Semiring::SPPF;
use Chalk::Grammar;
use Chalk::Parser;

1;

content.content:
     1→# ABOUTME: Earley parser implementation with Leo optimization for Chalk
     2→# ABOUTME: Provides EarleyItem, LeoItem, EarleyChart, and Parser classes
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→use Chalk::Semiring::Boolean;
     7→
     8→class Chalk::EarleyItem {
     9→    use overload '""' => 'key';
    10→
    11→    field $start_pos :param :reader;
    12→    field $rule      :param :reader;
    13→    field $dot_pos   :param :reader;
    14→    field $end_pos   :param :reader;
    15→    field $rule_id = $rule->id;
    16→    field @rhs     = $rule->rhs->@*;
    17→    field $complete    :reader = $dot_pos >= scalar(@rhs);
    18→    field $next_symbol :reader = $complete ? '' : $rhs[$dot_pos];
    19→    field $key = "Earley|$start_pos|$rule_id|$dot_pos|$end_pos";
    20→
    21→    method advance_dot() {
    22→        Chalk::EarleyItem->new(
    23→            start_pos => $start_pos,
    24→            rule      => $rule,
    25→            dot_pos   => $dot_pos + 1,
    26→            end_pos   => $end_pos,
    27→        );
    28→    }
    29→
    30→    method key(@args) { $key }
    31→}
    32→
    33→# Leo Items: Limited optimization for right-recursive grammar patterns
    34→#
    35→# This is a LIMITED implementation of Joop Leo's optimization (1991) for right-recursive
    36→# grammars.  It creates "Leo items" only in DETERMINISTIC cases where:
    37→# 1. Exactly one Earley item is waiting for the completed symbol
    38→# 2. The waiting item will be complete after this one reduction
    39→# 3. The rule is right-recursive (LHS appears as last RHS symbol)
    40→#
    41→# Why limited? Full Leo would create items even with multiple waiting items and maintain
    42→# a hash lookup by (position, symbol). Our grammar has 41 right-recursive rules, but
    43→# performance testing shows grammar complexity (960+ rules) is the main bottleneck,
    44→# not right-recursion specifically. This limited implementation provides O(n) behavior
    45→# for simple right-recursive chains (ArrowChain, StatementList) without the complexity
    46→# of full Leo.
    47→#
    48→# See t/optimization/test-leo-items.t for verification tests.
    49→# See issue #10 for detailed analysis and rationale.
    50→class Chalk::LeoItem {
    51→    use overload '""' => 'key';
    52→
    53→    field $symbol    :param :reader;
    54→    field $start_pos :param :reader;
    55→    field $end_pos   :param :reader;
    56→    field $top_item  :param :reader;
    57→    field $rule      :reader = $top_item->rule;
    58→
    59→    method complete()    { 1 }
    60→    method next_symbol() { }
    61→
    62→    method key(@args) {
    63→        return "LEO:$symbol|$start_pos|$end_pos";
    64→    }
    65→
    66→}
    67→
    68→class Chalk::EarleyChart {
    69→    field $semiring :param;
    70→    field %chart;
    71→    field @by_end_pos;
    72→    field %predicted;    # Track what we've predicted at each position
    73→    field %completed;    # Track what we've completed
    74→    field %waiting_for;  # Index: waiting_for{symbol}{pos} = [items waiting for symbol at pos]
    75→    field %leo_waiting_for;  # Index: leo_waiting_for{symbol}{pos} = [Leo items waiting for symbol at pos]
    76→
    77→    method add_item($earley_item) {
    78→        $chart{ $earley_item->key } = $earley_item;
    79→    }
    80→
    81→    method get_element($key) { $chart{$key} }
    82→
    83→    method add_element( $item, $element ) {
    84→        my $key     = $item->key;
    85→        my $current = $self->get_element($key);
    86→        $chart{$key} = $current ? $current + $element : $element;
    87→
    88→        my $end_pos = $item->end_pos;
    89→        push( $by_end_pos[$end_pos]->@*, $item );
    90→
    91→        # Index by what they're waiting for
    92→        if ($item isa Chalk::LeoItem) {
    93→            # Leo items are indexed by their symbol and end position
    94→            my $symbol = $item->symbol;
    95→            my $leo_end_pos = $item->end_pos;
    96→            $leo_waiting_for{$symbol} //= {};
    97→            my $leo_by_symbol = $leo_waiting_for{$symbol};
    98→            $leo_by_symbol->{$leo_end_pos} //= [];
    99→            my $leo_list = $leo_by_symbol->{$leo_end_pos};
   100→            push( $leo_list->@*, $item );
   101→        }
   102→        elsif (!$item->complete) {
   103→            # Regular items indexed by next_symbol
   104→            my $next_sym = $item->next_symbol;
   105→            if ($next_sym) {
   106→                my $waiting_end_pos = $item->end_pos;
   107→                $waiting_for{$next_sym} //= {};
   108→                my $waiting_by_sym = $waiting_for{$next_sym};
   109→                $waiting_by_sym->{$waiting_end_pos} //= [];
   110→                my $waiting_list = $waiting_by_sym->{$waiting_end_pos};
   111→                push( $waiting_list->@*, $item );
   112→            }
   113→        }
   114→
   115→        return $chart{$key};
   116→    }
   117→
   118→    method items_ending_at($end_pos) {
   119→        return $by_end_pos[$end_pos]->@* if $by_end_pos[$end_pos];
   120→        return;
   121→    }
   122→
   123→    method items_waiting_for($symbol, $pos) {
   124→        my $by_symbol = $waiting_for{$symbol};
   125→        if ($by_symbol && exists($by_symbol->{$pos})) {
   126→            return $by_symbol->{$pos}->@*;
   127→        }
   128→        return;
   129→    }
   130→
   131→    method leo_items_waiting_for($symbol, $pos) {
   132→        my $by_symbol = $leo_waiting_for{$symbol};
   133→        if ($by_symbol && exists($by_symbol->{$pos})) {
   134→            return $by_symbol->{$pos}->@*;
   135→        }
   136→        return;
   137→    }
   138→
   139→    method has_item($item) {
   140→        return exists( $chart{$item} );
   141→    }
   142→
   143→    method has_predicted( $nonterminal, $pos, $rule_id ) {
   144→        return exists( $predicted{"$nonterminal|$pos|$rule_id"} );
   145→    }
   146→
   147→    method mark_predicted( $nonterminal, $pos, $rule_id ) {
   148→        $predicted{"$nonterminal|$pos|$rule_id"} = 1;
   149→    }
   150→
   151→    method has_completed($item) {
   152→        return exists( $completed{$item} );
   153→    }
   154→
   155→    method mark_completed($item) {
   156→        $completed{$item} = 1;
   157→    }
   158→
   159→    method goal_value( $start_symbol, $n ) {
   160→
   161→        # Find all complete items that span [0,n] with LHS = start_symbol
   162→        my $result = $semiring->add_id;
   163→
   164→        my @items = $self->items_ending_at($n);
   165→
   166→        for my $item (@items) {
   167→            next unless $item->complete;
   168→            next unless $item->start_pos == 0;
   169→            next unless $item->rule->lhs eq $start_symbol;
   170→
   171→            my $element = $self->get_element($item);
   172→            if ($element) {
   173→                $result = $result + $element;
   174→
   175→                # Early termination for Boolean semiring: we only need to know
   176→                # IF a parse exists, not enumerate ALL parses. This prevents
   177→                # memory exhaustion when parsing highly ambiguous inputs like
   178→                # the grammar file itself (which has exponentially many parses).
   179→                # For other semirings (like Semantic), we need to accumulate ALL
   180→                # parses to get the correct result.
   181→                if ($semiring isa Chalk::Semiring::Boolean && $result != $semiring->add_id) {
   182→                    return $result;
   183→                }
   184→            }
   185→        }
   186→
   187→        # Check if we found any valid parses
   188→        return $result == $semiring->add_id ? undef : $result;
   189→    }
   190→}
   191→
   192→class Chalk::Parser {
   193→    field $semiring :param = Chalk::Semiring::Boolean->new();
   194→    field $grammar :param;
   195→    field $preprocess :param = [];  # Arrayref of preprocessor class names
   196→    field $input_string;  # Store input string for semantic actions
   197→
   198→    method parse_string($input) {
   199→        $input_string = $input;  # Store for semantic actions
   200→        # Apply preprocessors in sequence
   201→        for my $preprocessor_class ($preprocess->@*) {
   202→            next unless defined $preprocessor_class;
   203→
   204→            # Load the preprocessor module
   205→            my $file = $preprocessor_class;
   206→            my $search = '::';
   207→            my $replace = '/';
   208→            my $pos = index($file, $search);
   209→            while ($pos >= 0) {
   210→                substr($file, $pos, length($search), $replace);
   211→                $pos = index($file, $search, $pos + length($replace));
   212→            }
   213→            require "$file.pm";
   214→
   215→            # Apply preprocessing
   216→            my $preprocessor = $preprocessor_class->new(input => $input);
   217→            $preprocessor->transform();
   218→            $input = $preprocessor->output;
   219→        }
   220→
   221→        my $chart = Chalk::EarleyChart->new( semiring => $semiring );
   222→
   223→       # Initialize chart by predicting all rules for start symbol at position 0
   224→        my $start_symbol = $grammar->start_symbol;
   225→        for my $rule ( $grammar->rules_for($start_symbol) ) {
   226→            my $start_item = Chalk::EarleyItem->new(
   227→                start_pos => 0,
   228→                rule      => $rule,
   229→                dot_pos   => 0,
   230→                end_pos   => 0,
   231→            );
   232→
   233→            my $start_element = $semiring->init_element_from_rule($rule, 0, 0);
   234→            $chart->add_element( $start_item, $start_element );
   235→        }
   236→
   237→        # Process positions from 0 to end of string
   238→        my $pos             = 0;
   239→        my $input_length    = length($input);
   240→        my $last_active_pos = 0;
   241→
   242→        # Store input_string for semantic actions
   243→        $input_string = $input;
   244→
   245→        while ( $pos <= $input_length ) {
   246→            my @agenda_before = $chart->items_ending_at($pos);
   247→            $self->process_position_string( $pos, $chart, $input );
   248→
   249→            # Track the last position where we had active items
   250→            if ( @agenda_before > 0 ) {
   251→                $last_active_pos = $pos;
   252→            }
   253→
   254→            ++$pos;
   255→        }
   256→
   257→        my $result =
   258→          $chart->goal_value( $grammar->start_symbol, $input_length );
   259→
   260→        # Show where parsing actually stopped if it failed
   261→        if ( !$result && $last_active_pos < $input_length ) {
   262→            warn(
   263→"🔍 PARSING STOPPED: Reached position $last_active_pos of $input_length ("
   264→                  . sprintf( "%.1f", 100 * $last_active_pos / $input_length )
   265→                  . "%)\n" );
   266→        }
   267→
   268→        return $result;
   269→    }
   270→
   271→    method process_position_string( $pos, $chart, $input_string ) {
   272→        my @agenda = $chart->items_ending_at($pos);
   273→
   274→        my $item;
   275→        while ( $item = shift(@agenda) ) {
   276→            my $element = $chart->get_element($item);
   277→            next unless defined($element);
   278→
   279→            if ( $item->complete ) {
   280→                $self->complete( $item, $element, $chart, \@agenda );
   281→            }
   282→            else {
   283→                my $next_sym = $item->next_symbol;
   284→                if (defined($next_sym)) {
   285→                    if ($grammar->is_nonterminal($next_sym) ) {
   286→                        $self->predict( $item, $next_sym, $chart, \@agenda );
   287→                    }
   288→                    else {
   289→                        # Try to match terminal with lexeme support
   290→                        my $pattern = $item->rule->terminal_to_regex($next_sym);
   291→                        pos($input_string) = $pos;
   292→                        my $match_pattern = qr/\G($pattern)/;
   293→                        if ( $input_string =~ $match_pattern ) {
   294→                            my $match_length = length($1);
   295→                            $self->scan( $item, $element, $chart, $pos,
   296→                                $match_length );
   297→                        }
   298→
   299→                        # Aycock-Horspool optimization for nullable terminals:
   300→                        # If the terminal can match empty string, also advance dot
   301→                        if (ref($next_sym) eq 'Regexp' && "" =~ $next_sym) {
   302→                            my $advanced_item = Chalk::EarleyItem->new(
   303→                                start_pos => $item->start_pos,
   304→                                rule      => $item->rule,
   305→                                dot_pos   => $item->dot_pos + 1,
   306→                                end_pos   => $item->end_pos
   307→                            );
   308→
   309→                            unless ( $chart->has_item($advanced_item) ) {
   310→                                $chart->add_element( $advanced_item, $element );
   311→                                push( @agenda, $advanced_item );
   312→                            }
   313→                        }
   314→                    }
   315→                }
   316→            }
   317→        }
   318→    }
   319→
   320→    method complete( $completed_item, $completed_element, $chart, $agenda ) {
   321→
   322→        # Check if we've already completed this item
   323→        return if $chart->has_completed($completed_item);
   324→        $chart->mark_completed($completed_item);
   325→
   326→        my $lhs = $completed_item->rule->lhs;
   327→
   328→        # For Semantic semiring, evaluate the completed rule
   329→        # NOTE: We evaluate and set the focus, but keep the children so they can
   330→        # be accessed by parent rules during their evaluation
   331→        if ($semiring isa Chalk::Semiring::Semantic) {
   332→            # IMPORTANT: Get the LATEST element from the chart, not the one passed in!
   333→            # The element passed in might be stale if multiply operations happened
   334→            my $latest_element = $chart->get_element($completed_item);
   335→            if ($latest_element) {
   336→                $completed_element = $latest_element;
   337→            }
   338→
   339→            my $ctx = $completed_element->context;
   340→            my $evaluated_value = $completed_item->rule->evaluate($ctx);
   341→
   342→            # Create new context with evaluated focus but preserve children
   343→            my $new_ctx = Chalk::EvalContext->new(
   344→                focus => $evaluated_value,
   345→                children => $ctx->children,
   346→                start_pos => $ctx->start_pos,
   347→                end_pos => $ctx->end_pos,
   348→                env => $ctx->env,
   349→                grammar => $ctx->grammar,
   350→                rule => $ctx->rule
   351→            );
   352→
   353→            # Update the completed element with evaluated context
   354→            $completed_element = Chalk::Semiring::SemanticElement->new(
   355→                value => 1,
   356→                context => $new_ctx
   357→            );
   358→
   359→            # Update the chart with evaluated element so parent rules can access the evaluated focus
   360→            # The element has both the evaluated focus AND the accumulated children
   361→            $chart->add_element($completed_item, $completed_element);
   362→        }
   363→
   364→        # Use indexed lookups to get items waiting for this symbol
   365→        # This avoids the expensive grep operations with isa checks
   366→        my @waiting_for_lhs = $chart->items_waiting_for($lhs, $completed_item->start_pos);
   367→        my @leo_waiting = $chart->leo_items_waiting_for($lhs, $completed_item->start_pos);
   368→
   369→  # Check for deterministic reduction (only if no Leo items waiting)
   370→  # Leo items are only for deterministic right-recursive chains where:
   371→  # 1. Only one item is waiting for this LHS
   372→  # 2. The waiting item will be complete after this reduction
   373→  # 3. The rule is right-recursive
   374→  #
   375→  # NOTE: Joop Leo's second optimization for left-recursion could be implemented
   376→  # here, but performance testing shows left-recursion is already faster than
   377→  # right-recursion in our Earley implementation, so it's not needed.
   378→        if (   @waiting_for_lhs == 1
   379→            && @leo_waiting == 0
   380→            && $waiting_for_lhs[0]->rule->is_right_recursive
   381→            && $waiting_for_lhs[0]->dot_pos ==
   382→            scalar( $waiting_for_lhs[0]->rule->rhs->@* ) - 1 )
   383→        {
   384→            my $waiting_item = $waiting_for_lhs[0];
   385→
   386→            # Use completed item's end position
   387→            my $leo = Chalk::LeoItem->new(
   388→                symbol    => $lhs,
   389→                start_pos => $waiting_item->start_pos,
   390→                end_pos   => $completed_item->end_pos,
   391→                top_item  => $waiting_item,
   392→            );
   393→
   394→            my $waiting_element = $chart->get_element($waiting_item);
   395→            next unless $waiting_element;
   396→            my $combined_element = $waiting_element * $completed_element;
   397→            $chart->add_element( $leo, $combined_element );
   398→            push( $agenda->@*, $leo );
   399→            return;    # Skip normal completion
   400→        }
   401→
   402→        # Normal completion for regular items
   403→        for my $waiting_item (@waiting_for_lhs) {
   404→
   405→            my $waiting_element = $chart->get_element($waiting_item);
   406→            next unless $waiting_element;
   407→
   408→            # Semiring multiplication ⊗ combines sequential components
   409→            my $combined_element = $waiting_element * $completed_element;
   410→
   411→            my $new_item = Chalk::EarleyItem->new(
   412→                start_pos => $waiting_item->start_pos,
   413→                rule      => $waiting_item->rule,
   414→                dot_pos   => $waiting_item->dot_pos + 1,
   415→                end_pos   => $completed_item->end_pos
   416→            );
   417→
   418→            # Only add if not already in chart
   419→            unless ( $chart->has_item($new_item) ) {
   420→                $chart->add_element( $new_item, $combined_element );
   421→                push( $agenda->@*, $new_item );
   422→            }
   423→        }
   424→
   425→        # Handle Leo items waiting for this completion
   426→        for my $leo_item (@leo_waiting) {
   427→
   428→            # Unpack the Leo chain to get the original waiting item
   429→            my $current = $leo_item->top_item;
   430→            while ( $current isa Chalk::LeoItem ) {
   431→                $current = $current->top_item;
   432→            }
   433→
   434→            # Now $current is the original EarleyItem at the bottom of the chain
   435→            # Complete it with the current completed item
   436→            my $waiting_element = $chart->get_element($leo_item);
   437→            next unless $waiting_element;
   438→            my $combined_element = $waiting_element * $completed_element;
   439→
   440→            my $new_item = Chalk::EarleyItem->new(
   441→                start_pos => $current->start_pos,
   442→                rule      => $current->rule,
   443→                dot_pos   => $current->dot_pos + 1,
   444→                end_pos   => $completed_item->end_pos
   445→            );
   446→
   447→            # Only add if not already in chart
   448→            unless ( $chart->has_item($new_item) ) {
   449→                $chart->add_element( $new_item, $combined_element );
   450→                push( $agenda->@*, $new_item );
   451→            }
   452→        }
   453→    }
   454→
   455→    method predict( $item, $nonterminal, $chart, $agenda ) {
   456→        my $pos = $item->end_pos;
   457→
   458→# Check if we've already predicted this nonterminal from this rule at this position
   459→# Multiple rules can predict the same nonterminal, so we track by rule origin
   460→        return if $chart->has_predicted( $nonterminal, $pos, $item->rule->id );
   461→        $chart->mark_predicted( $nonterminal, $pos, $item->rule->id );
   462→
   463→        for my $rule ( $grammar->rules_for($nonterminal) ) {
   464→            my $predicted_item = Chalk::EarleyItem->new(
   465→                start_pos => $pos,
   466→                rule      => $rule,
   467→                dot_pos   => 0,
   468→                end_pos   => $pos
   469→            );
   470→
   471→            # Only add if not already in chart
   472→            unless ( $chart->has_item($predicted_item) ) {
   473→                my $rule_element = $semiring->init_element_from_rule($rule, $pos, $pos);
   474→                $chart->add_element( $predicted_item, $rule_element );
   475→                push( $agenda->@*, $predicted_item );
   476→            }
   477→        }
   478→
   479→        # Aycock-Horspool optimization: if the nonterminal is nullable,
   480→        # we can also advance the dot past it immediately
   481→        if ( $grammar->is_nullable($nonterminal) ) {
   482→            my $advanced_item = Chalk::EarleyItem->new(
   483→                start_pos => $item->start_pos,
   484→                rule      => $item->rule,
   485→                dot_pos   => $item->dot_pos + 1,
   486→                end_pos   => $item->end_pos
   487→            );
   488→
   489→            # Only add if not already present
   490→            unless ( $chart->has_item($advanced_item) ) {
   491→                my $current_element = $chart->get_element($item);
   492→                if ($current_element) {
   493→                    $chart->add_element( $advanced_item, $current_element );
   494→                    push( $agenda->@*, $advanced_item );
   495→                }
   496→            }
   497→        }
   498→    }
   499→
   500→    method scan( $item, $element, $chart, $pos, $match_length ) {
   501→        my $scanned_item = Chalk::EarleyItem->new(
   502→            start_pos => $item->start_pos,
   503→            rule      => $item->rule,
   504→            dot_pos   => $item->dot_pos + 1,
   505→            end_pos   => $pos + $match_length
   506→        );
   507→
   508→        # For Semantic semiring, extract the matched terminal string value
   509→        # and multiply with current element to accumulate terminals in children
   510→        my $scanned_element;
   511→        if ($semiring isa Chalk::Semiring::Semantic) {
   512→            # Extract the matched terminal value from input string
   513→            my $matched_value = substr($input_string, $pos, $match_length);
   514→
   515→            # Create a context with the terminal value as focus
   516→            my $terminal_ctx = Chalk::EvalContext->new(
   517→                focus => $matched_value,
   518→                children => [],
   519→                start_pos => $pos,
   520→                end_pos => $pos + $match_length,
   521→                env => $semiring->grammar->start_symbol,  # Use grammar
   522→                grammar => $grammar,
