     1→# ABOUTME: SPPF (Shared Packed Parse Forest) implementation for Chalk parser
     2→# ABOUTME: Provides classes for representing ambiguous parse forests and Viterbi elements
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→use Chalk::Base;
     7→use Chalk::Semiring::Viterbi;
     8→use Chalk::Semiring::Composite;
     9→
    10→# SPPF (Shared Packed Parse Forest) Node Classes
    11→class Chalk::Semiring::SPPFSymbolNode {
    12→    use overload '""' => 'to_string';
    13→
    14→    field $symbol    :param :reader;
    15→    field $start_pos :param :reader;
    16→    field $end_pos   :param :reader;
    17→    field @packed_nodes;
    18→
    19→    method add_packed_node($packed_node) {
    20→        my @new_children = $packed_node->children();
    21→
    22→        # Check if we already have a packed node with the same children
    23→        for my $existing (@packed_nodes) {
    24→            my @existing_children = $existing->children();
    25→
    26→            # Different sizes can't be duplicates, skip
    27→            next unless @existing_children == @new_children;
    28→
    29→            # Same size - check if all children are identical references
    30→            my $all_match = 1;
    31→            for my $i (0..$#existing_children) {
    32→                unless (refaddr($existing_children[$i]) == refaddr($new_children[$i])) {
    33→                    $all_match = 0;
    34→                    last;
    35→                }
    36→            }
    37→            return if $all_match;  # Found exact duplicate, don't add
    38→        }
    39→
    40→        push( @packed_nodes, $packed_node );
    41→    }
    42→
    43→    method packed_nodes() { @packed_nodes }
    44→
    45→    method to_string(@args) {
    46→        return "$symbol\[$start_pos(),$end_pos()\]";
    47→    }
    48→
    49→    method key() { "$symbol()|$start_pos()|$end_pos()" }
    50→}
    51→
    52→class Chalk::Semiring::SPPFPackedNode {
    53→    use overload '""' => 'to_string';
    54→
    55→    field $rule :param :reader;
    56→    field @children;
    57→
    58→    method add_child($child) {
    59→        push( @children, $child );
    60→    }
    61→
    62→    method children() { @children }
    63→
    64→    method to_string(@args) {
    65→        my $rule_str     = $rule ? $rule->to_string : "terminal";
    66→        my $children_str = join( ", ", map { "$_" } @children );
    67→        return "$rule_str -> [$children_str]";
    68→    }
    69→}
    70→
    71→class Chalk::Semiring::SPPFTerminalNode {
    72→    use overload '""' => 'to_string';
    73→
    74→    field $symbol    :param :reader;
    75→    field $start_pos :param :reader;
    76→    field $end_pos   :param :reader;
    77→
    78→    method to_string(@args) {
    79→        return "'$symbol'\[$start_pos(),$end_pos()\]";
    80→    }
    81→
    82→    method key() { "$symbol()|$start_pos()|$end_pos()" }
    83→}
    84→
    85→# Pure SPPF Element - only tracks forest structure, no scoring
    86→class Chalk::Semiring::SPPFElement :isa(Chalk::Element) {
    87→    field $sppf_node :param :reader;
    88→    field $forest    :param :reader;
    89→
    90→    method multiply( $other, $swap = undef ) {
    91→        # Create new combined SPPF node representing sequence
    92→        my $other_node = $other->sppf_node();
    93→        my $combined_node =
    94→          $forest->create_sequence_node( $sppf_node, $other_node );
    95→
    96→        return Chalk::Semiring::SPPFElement->new(
    97→            sppf_node => $combined_node,
    98→            forest    => $forest
    99→        );
   100→    }
   101→
   102→    method add( $other, $swap = undef ) {
   103→        my $self_start = $sppf_node->start_pos();
   104→        my $self_end = $sppf_node->end_pos();
   105→        my $other_node = $other->sppf_node();
   106→        my $other_start = $other_node->start_pos();
   107→        my $other_end = $other_node->end_pos();
   108→
   109→        # Merge alternatives if they span the same range
   110→        if ($self_start == $other_start && $self_end == $other_end) {
   111→            $forest->add_alternative( $sppf_node, $other_node );
   112→        }
   113→
   114→        # Prefer element that went further (for consistency with composite pattern)
   115→        # This allows SPPF to work correctly when composed with scoring semirings
   116→        return $self_end >= $other_end ? $self : $other;
   117→    }
   118→
   119→    method equals( $other, $swap = undef ) {
   120→        return 0 unless ref($other) eq ref($self);
   121→        # Two SPPF elements are equal if they reference the same node
   122→        my $other_node = $other->sppf_node();
   123→        return refaddr($sppf_node) == refaddr($other_node);
   124→    }
   125→
   126→    method to_string(@args) {
   127→        return "SPPF:$sppf_node";
   128→    }
   129→}
   130→
   131→# Pure SPPF Semiring - only forest tracking, no Viterbi scoring
   132→class Chalk::Semiring::SPPF :isa(Chalk::Semiring) {
   133→    field $forest :reader;
   134→    field $root_element :reader;
   135→    field $mul_id :reader;
   136→    field $add_id :reader;
   137→
   138→    ADJUST {
   139→        $forest = Chalk::Semiring::SPPFForest->new();
   140→
   141→        $root_element = Chalk::Semiring::SPPFElement->new(
   142→            sppf_node => $forest->get_or_create_symbol_node( "ROOT", 0, 0 ),
   143→            forest    => $forest
   144→        );
   145→
   146→        $mul_id = Chalk::Semiring::SPPFElement->new(
   147→            sppf_node => $forest->get_or_create_symbol_node( "ε", 0, 0 ),
   148→            forest    => $forest
   149→        );
   150→
   151→        $add_id = Chalk::Semiring::SPPFElement->new(
   152→            sppf_node => $forest->get_or_create_symbol_node( "⊥", 0, 0 ),
   153→            forest    => $forest
   154→        );
   155→    }
   156→
   157→    method init_element_from_rule($rule, $start_pos = 0, $end_pos = 0) {
   158→        my $lhs = $rule->lhs();
   159→        my $symbol_node =
   160→          $forest->get_or_create_symbol_node( $lhs, $start_pos, $end_pos );
   161→
   162→        return Chalk::Semiring::SPPFElement->new(
   163→            sppf_node => $symbol_node,
   164→            forest    => $forest
   165→        );
   166→    }
   167→}
   168→
   169→# SPPFViterbi Element - now a wrapper around Composite(SPPF, Viterbi)
   170→# Provides backward compatibility with previous SPPFViterbiElement API
   171→class Chalk::Semiring::SPPFViterbiElement :isa(Chalk::Element) {
   172→    field $composite :param :reader;
   173→
   174→    # Convenience accessors for backward compatibility
   175→    method score() {
   176→        return $composite->element_at(1)->score();
   177→    }
   178→
   179→    method path() {
   180→        return $composite->element_at(1)->path();
   181→    }
   182→
   183→    method sppf_node() {
   184→        return $composite->element_at(0)->sppf_node();
   185→    }
   186→
   187→    method forest() {
   188→        return $composite->element_at(0)->forest();
   189→    }
   190→
   191→    # Delegate core operations to composite
   192→    method multiply( $other, $swap = undef ) {
   193→        my $other_composite = $other->composite();
   194→        my $result = $composite->multiply($other_composite);
   195→        return Chalk::Semiring::SPPFViterbiElement->new(
   196→            composite => $result
   197→        );
   198→    }
   199→
   200→    method add( $other, $swap = undef ) {
   201→        my $other_composite = $other->composite();
   202→        my $result = $composite->add($other_composite);
   203→        return Chalk::Semiring::SPPFViterbiElement->new(
   204→            composite => $result
   205→        );
   206→    }
   207→
   208→    method equals( $other, $swap = undef ) {
   209→        return 0 unless ref($other) eq ref($self);
   210→        my $other_composite = $other->composite();
   211→        return $composite->equals($other_composite);
   212→    }
   213→
   214→    method to_string(@args) {
   215→        my $score = $self->score();
   216→        my $path = $self->path();
   217→        my $node = $self->sppf_node();
   218→        return sprintf( '%.4f[%s] SPPF:%s',
   219→            exp($score), join( ',', $path->@* ), $node );
   220→    }
   221→
   222→    # Backward compatibility helpers
   223→    method probability() {
   224→        my $score = $self->score();
   225→        return exp($score);
   226→    }
   227→    method best_path() {
   228→        my $path = $self->path();
   229→        return $path->[0];
   230→    }
   231→
   232→    method validate_complete_parse($input_length) {
   233→        my $node = $self->sppf_node();
   234→        return $node->start_pos() == 0 && $node->end_pos() == $input_length;
   235→    }
   236→}
   237→
   238→class Chalk::Semiring::SPPFForest {
   239→    field %symbol_nodes;
   240→    field %terminal_nodes;
   241→
   242→    method get_or_create_symbol_node( $symbol, $start_pos, $end_pos ) {
   243→        my $key = "$symbol|$start_pos|$end_pos";
   244→        return $symbol_nodes{$key} //= Chalk::Semiring::SPPFSymbolNode->new(
   245→            symbol    => $symbol,
   246→            start_pos => $start_pos,
   247→            end_pos   => $end_pos
   248→        );
   249→    }
   250→
   251→    method get_or_create_terminal_node( $symbol, $start_pos, $end_pos ) {
   252→        my $key = "$symbol|$start_pos|$end_pos";
   253→        return $terminal_nodes{$key} //= Chalk::Semiring::SPPFTerminalNode->new(
   254→            symbol    => $symbol,
   255→            start_pos => $start_pos,
   256→            end_pos   => $end_pos
   257→        );
   258→    }
   259→
   260→    method create_sequence_node( $left_node, $right_node ) {
   261→        my $start = $left_node->start_pos();
   262→        my $end = $right_node->end_pos();
   263→
   264→        my $seq_node = $self->get_or_create_symbol_node( "SEQ", $start, $end );
   265→
   266→        my $packed = Chalk::Semiring::SPPFPackedNode->new( rule => undef );
   267→        $packed->add_child($left_node);
   268→        $packed->add_child($right_node);
   269→        $seq_node->add_packed_node($packed);  # add_packed_node handles de-duplication
   270→
   271→        return $seq_node;
   272→    }
   273→
   274→    method add_alternative( $node1, $node2 ) {
   275→        my $class = 'Chalk::Semiring::SPPFSymbolNode';
   276→        return unless ref($node1) eq $class && ref($node2) eq $class;
   277→
   278→        # Merge all packed nodes from node2 into node1
   279→        my @nodes = $node2->packed_nodes();
   280→        for my $packed (@nodes) {
   281→            $node1->add_packed_node($packed);  # add_packed_node handles de-duplication
   282→        }
   283→    }
   284→
   285→    method nodes() {
   286→        return \%symbol_nodes;
   287→    }
   288→}
   289→
   290→# SPPFViterbi Semiring - now implemented as Composite(SPPF, Viterbi)
   291→# Provides backward compatibility while using clean separation of concerns
   292→class Chalk::Semiring::SPPFViterbiSemiring :isa(Chalk::Semiring) {
   293→    field $composite :reader;
