     1→#!/usr/bin/env perl
     2→# ABOUTME: CLI application for Chalk parser with grammar loading and input processing
     3→# ABOUTME: Supports grammar modules via -g option (e.g., -g Perl loads Chalk::Grammar::Perl)
     4→use 5.42.0;
     5→use experimental qw(class builtin keyword_any keyword_all);
     6→use utf8;
     7→use open qw(:std :utf8);
     8→use FindBin qw($RealBin);
     9→use lib "$RealBin/lib";
    10→
    11→use Chalk;
    12→
    13→# Main execution when run as script
    14→if ( !caller ) {
    15→    # Parse command line options
    16→    my $grammar_module = "Perl";  # default grammar module
    17→    my $semiring_type = "SPPF";   # default semiring
    18→    my $syntax_check_mode = 0;    # -c flag for syntax checking
    19→    my $preprocess = ['Chalk::Preprocessor::Heredoc'];  # default to Heredoc
    20→    my @remaining_args;
    21→
    22→    my $i = 0;
    23→    while ($i <= $#ARGV) {
    24→        if ($ARGV[$i] eq '-g' && $i < $#ARGV) {
    25→            $grammar_module = $ARGV[$i + 1];
    26→            $i += 2; # skip both -g and the grammar module name
    27→        } elsif ($ARGV[$i] eq '--semiring' && $i < $#ARGV) {
    28→            $semiring_type = $ARGV[$i + 1];
    29→            $i += 2; # skip both --semiring and the semiring type
    30→        } elsif ($ARGV[$i] eq '-c') {
    31→            $syntax_check_mode = 1;
    32→            $semiring_type = "Boolean";  # -c implies Boolean semiring
    33→            $i++;
    34→        } elsif ($ARGV[$i] eq '--preprocess') {
    35→            $preprocess = ['Chalk::Preprocessor::Heredoc'];  # Enable heredoc preprocessing
    36→            $i++;
    37→        } else {
    38→            push @remaining_args, $ARGV[$i];
    39→            $i++;
    40→        }
    41→    }
    42→    @ARGV = @remaining_args;
    43→
    44→    # Build grammar from BNF file
    45→    use File::Basename qw(dirname);
    46→    use File::Spec;
    47→    use Chalk::Grammar;
    48→
    49→    our $chalk_grammar;
    50→
    51→    # Map grammar names to BNF files
    52→    my %grammar_files = (
    53→        'Perl'  => 'perl.bnf',
    54→        'Chalk' => 'chalk.bnf',
    55→    );
    56→
    57→    if (exists $grammar_files{$grammar_module}) {
    58→        # Load from BNF file
    59→        my $bnf_file = File::Spec->catfile($RealBin, 'grammar', $grammar_files{$grammar_module});
    60→        open my $fh, '<:utf8', $bnf_file or die "Cannot open $bnf_file: $!";
    61→        my $content = do { local $/; <$fh> };
    62→        close $fh;
    63→
    64→        # Both Perl and Chalk grammars use 'Program' as start symbol
    65→        my $start_symbol = ($grammar_module eq 'Perl' || $grammar_module eq 'Chalk') ? 'Program' : undef;
    66→        $chalk_grammar = Chalk::Grammar->build_from_bnf($content, $start_symbol);
    67→    } else {
    68→        # Try loading as a module
    69→        my $full_module_name = $grammar_module;
    70→        unless ($full_module_name =~ /::/) {
    71→            $full_module_name = "Chalk::Grammar::$full_module_name";
    72→        }
    73→
    74→        my $grammar_file = $full_module_name;
    75→        $grammar_file =~ s{::}{/}g;
    76→        $grammar_file .= ".pm";
    77→
    78→        eval {
    79→            require $grammar_file;
    80→            $full_module_name->import();
    81→        };
    82→        if ($@) {
    83→            die("Error: Failed to load grammar module '$full_module_name': $@\n");
    84→        }
    85→
    86→        # Try to get $chalk_grammar export
    87→        no strict 'refs';
    88→        $chalk_grammar = ${"${full_module_name}::chalk_grammar"};
    89→    }
    90→
    91→    # Verify grammar loaded
    92→    if ( !defined($chalk_grammar) ) {
    93→        die("Error: Grammar not loaded for '$grammar_module'!\n");
    94→    }
    95→
    96→    # Read input from STDIN or command line file
    97→    my $input;
    98→    if (@ARGV) {
    99→        # Read from file
   100→        my $filename = $ARGV[0];
   101→        open( my $fh, '<', $filename ) or die("Cannot open $filename: $!\n");
   102→        local $/;    # slurp mode
   103→        $input = <$fh>;
   104→        close($fh);
   105→    }
   106→    else {
   107→        # Read from STDIN
   108→        local $/;    # slurp mode
   109→        $input = <STDIN>;
   110→    }
   111→
   112→    chomp($input) if defined($input);
   113→
   114→    if ( defined($input) && length($input) > 0 ) {
   115→        # Create semiring based on type
   116→        my $semiring;
   117→        if ($semiring_type eq "Boolean") {
   118→            require Chalk::Semiring::Boolean;
   119→            $semiring = Chalk::Semiring::Boolean->new();
   120→        } elsif ($semiring_type eq "Position") {
   121→            require Chalk::Semiring::Position;
   122→            $semiring = Chalk::Semiring::Position->new();
   123→        } elsif ($semiring_type eq "SPPF") {
   124→            require Chalk::Semiring::SPPF;
   125→            $semiring = Chalk::Semiring::SPPFViterbiSemiring->new();
   126→        } else {
   127→            die("Error: Unknown semiring type '$semiring_type'. Use 'Boolean', 'Position', or 'SPPF'\n");
   128→        }
   129→
   130→        # Create parser with grammar and semiring
   131→        my $parser = Chalk::Parser->new(
   132→            grammar => $chalk_grammar,
   133→            semiring => $semiring,
   134→            preprocess => $preprocess
   135→        );
   136→
   137→        # Parse the input
   138→        my $result = $parser->parse_string($input);
   139→
   140→        # Print the result
   141→        if ($result) {
   142→            if ($syntax_check_mode) {
   143→                print("$ARGV[0] syntax OK\n") if @ARGV;
   144→                print("syntax OK\n") unless @ARGV;
