#!/usr/bin/env perl
# ABOUTME: Tests for Parser integration with semantic actions
# ABOUTME: Validates that Parser calls evaluate() when using Semantic semiring

use 5.42.0;
use warnings;
use Test::More;

use lib 'lib';
use Test::Chalk::Grammar;
use Chalk::Grammar;
use Chalk::Parser;
use Chalk::Semiring::Semantic;

# Test that Parser works with Semantic semiring
{
    my $grammar = Test::Chalk::Grammar->build_grammar(
        rules => [
            ['S' => ['a', 'b']],
        ]
    );

    my $semiring = Chalk::Semiring::Semantic->new(
        env => {},
        grammar => $grammar
    );

    my $parser = Chalk::Parser->new(
        grammar => $grammar,
        semiring => $semiring
    );

    # Simple test - just verify it doesn't crash
    my $result = $parser->parse_string("ab");

    ok($result, 'Parser with Semantic semiring can parse');
    isa_ok($result, 'Chalk::Semiring::SemanticElement', 'Result is a SemanticElement');
}

# Test with custom evaluation rule
{
    package CustomAddRule {
        use 5.42.0;
        use experimental 'class';

        class CustomAddRule :isa(Chalk::GrammarRule) {
            # Override evaluate to sum numeric values
            method evaluate($context) {
                my @children = $context->children->@*;
                return 0 unless @children >= 3;

                my $left = $children[0]->extract;
                my $op = $children[1]->extract;
                my $right = $children[2]->extract;

                if ($op eq '+' && defined($left) && defined($right)) {
                    return $left + $right;
                }

                return [$left, $op, $right];
            }
        }
    }

    my $add_rule = CustomAddRule->new(
        lhs => 'Expr',
        rhs => [qr/\d+/, qr/\+/, qr/\d+/]
    );

    my $grammar = Chalk::Grammar->new(
        rules => { 'Expr' => [$add_rule] },
        start_symbol => 'Expr'
    );

    my $semiring = Chalk::Semiring::Semantic->new(
        env => {},
        grammar => $grammar
    );

    my $parser = Chalk::Parser->new(
        grammar => $grammar,
        semiring => $semiring
    );

    my $result = $parser->parse_string("5+3");

    ok($result, 'Parser with custom evaluate rule can parse');
}

# Test that default evaluate() is called
{
    my $grammar = Test::Chalk::Grammar->build_grammar(
        rules => [
            ['S' => ['x']],
        ]
    );

    my $semiring = Chalk::Semiring::Semantic->new(
        env => {},
        grammar => $grammar
    );

    my $parser = Chalk::Parser->new(
        grammar => $grammar,
        semiring => $semiring
    );

    my $result = $parser->parse_string("x");

    ok($result, 'Parser with default evaluate can parse');
}

done_testing();

#!/usr/bin/env perl
# ABOUTME: Tests for GrammarRule evaluate() method for semantic actions
# ABOUTME: Validates default implementation returns child values as array

use 5.42.0;
use warnings;
use Test::More;

use lib 'lib';
use Test::Chalk::Grammar;
use Chalk::Grammar;
use Chalk::EvalContext;

# Test that GrammarRule has evaluate method
{
    my $grammar = Test::Chalk::Grammar->build_grammar(
        rules => [
            ['S' => ['a', 'b']],
        ]
    );

    my $rule = $grammar->rules->{'S'}->[0];
    ok($rule->can('evaluate'), 'GrammarRule has evaluate method');
}

# Test default evaluate implementation with no children
{
    my $grammar = Test::Chalk::Grammar->build_grammar(
        rules => [
            ['S' => []],  # Empty production
        ]
    );

    my $rule = $grammar->rules->{'S'}->[0];

    my $ctx = Chalk::EvalContext->new(
        focus => undef,
        children => [],
        start_pos => 0,
        end_pos => 0,
        env => {},
        grammar => $grammar,
        rule => $rule
    );

    my $result = $rule->evaluate($ctx);

    is_deeply($result, [], 'evaluate returns empty array for no children');
}

# Test default evaluate implementation with children
{
    my $grammar = Test::Chalk::Grammar->build_grammar(
        rules => [
            ['S' => ['a', 'b', 'c']],
        ]
    );

    my $rule = $grammar->rules->{'S'}->[0];

    # Create child contexts with values
    my $child1 = Chalk::EvalContext->new(
        focus => "first",
        children => [],
        start_pos => 0,
        end_pos => 5,
        env => {},
        grammar => $grammar,
        rule => undef
    );

    my $child2 = Chalk::EvalContext->new(
        focus => "second",
        children => [],
        start_pos => 5,
        end_pos => 11,
        env => {},
        grammar => $grammar,
        rule => undef
    );

    my $child3 = Chalk::EvalContext->new(
        focus => "third",
        children => [],
        start_pos => 11,
        end_pos => 16,
        env => {},
        grammar => $grammar,
        rule => undef
    );

    my $ctx = Chalk::EvalContext->new(
        focus => undef,
        children => [$child1, $child2, $child3],
        start_pos => 0,
        end_pos => 16,
        env => {},
        grammar => $grammar,
        rule => $rule
    );

    my $result = $rule->evaluate($ctx);

    is_deeply($result, ["first", "second", "third"],
              'evaluate returns array of child values');
}

# Test evaluate can access rule information
{
    my $grammar = Test::Chalk::Grammar->build_grammar(
        rules => [
            ['Expression' => ['Number', '+', 'Number']],
        ]
    );

    my $rule = $grammar->rules->{'Expression'}->[0];

    my $child1 = Chalk::EvalContext->new(
        focus => 5,
        children => [],
        start_pos => 0,
        end_pos => 1,
        env => {},
        grammar => $grammar,
        rule => undef
    );

    my $child2 = Chalk::EvalContext->new(
        focus => "+",
        children => [],
        start_pos => 1,
        end_pos => 2,
        env => {},
        grammar => $grammar,
        rule => undef
    );

    my $child3 = Chalk::EvalContext->new(
        focus => 3,
        children => [],
        start_pos => 2,
        end_pos => 3,
        env => {},
        grammar => $grammar,
        rule => undef
    );

    my $ctx = Chalk::EvalContext->new(
        focus => undef,
        children => [$child1, $child2, $child3],
        start_pos => 0,
        end_pos => 3,
        env => {},
        grammar => $grammar,
        rule => $rule
    );

    my $result = $rule->evaluate($ctx);

    is_deeply($result, [5, "+", 3], 'evaluate extracts all child values');
}

# Test that evaluate can be subclassed
{
    package TestRule {
        use 5.42.0;
        use experimental 'class';

        class TestRule :isa(Chalk::GrammarRule) {
            # Override evaluate to sum numeric children
            method evaluate($context) {
                my $sum = 0;
                for my $child ($context->children->@*) {
                    my $val = $child->extract;
                    $sum += $val if defined($val) && $val =~ /^\d+$/;
                }
                return $sum;
            }
        }
    }

    my $rule = TestRule->new(
        lhs => 'Sum',
        rhs => ['a', 'b', 'c']
    );

    my $child1 = Chalk::EvalContext->new(
        focus => 10,
        children => [],
        start_pos => 0,
        end_pos => 2,
        env => {},
        grammar => undef,
        rule => undef
    );

    my $child2 = Chalk::EvalContext->new(
        focus => 20,
        children => [],
        start_pos => 2,
        end_pos => 4,
        env => {},
        grammar => undef,
        rule => undef
    );

    my $child3 = Chalk::EvalContext->new(
        focus => 30,
        children => [],
        start_pos => 4,
        end_pos => 6,
        env => {},
        grammar => undef,
        rule => undef
    );

    my $ctx = Chalk::EvalContext->new(
        focus => undef,
        children => [$child1, $child2, $child3],
        start_pos => 0,
        end_pos => 6,
        env => {},
        grammar => undef,
        rule => $rule
    );

    my $result = $rule->evaluate($ctx);

    is($result, 60, 'subclassed evaluate can override default behavior');
}

done_testing();

