# ABOUTME: Semantic action for Grammar rule - builds final Chalk::Grammar object
# ABOUTME: Collects all grammar rules from LineList and constructs Grammar

use 5.42.0;
use experimental 'class';
use Chalk::Grammar;

class Chalk::Grammar::BNF::Rule::Grammar :isa(Chalk::GrammarRule) {
    method evaluate($context) {
        # Grammar -> LineList
        # Collect all rules from LineList
        my $line_list = $context->child(0);

        # line_list should be array of Chalk::GrammarRule objects
        my @rules = ref($line_list) eq 'ARRAY' ? $line_list->@* : ();

        # Filter out undef values (comments, blank lines)
        @rules = grep { defined($_) } @rules;

        # Group rules by LHS into hash structure
        my %rules_hash = ();
        for my $rule (@rules) {
            my $lhs = $rule->lhs;
            $rules_hash{$lhs} //= [];
            my $lhs_rules = $rules_hash{$lhs};
            push( $lhs_rules->@*, $rule );
        }

        # Extract start symbol from first rule
        my $start_symbol = @rules ? $rules[0]->lhs : '';

        # Build grammar directly with Chalk::Grammar->new()
        my $grammar = Chalk::Grammar->new(
            rules        => \%rules_hash,
            start_symbol => $start_symbol
        );
        return $grammar;
    }
}

# ABOUTME: Semantic action for GrammarRule - creates Chalk::GrammarRule objects
# ABOUTME: Extracts nonterminal name and RHS elements and wraps in GrammarRule object

use 5.42.0;
use experimental 'class';

class Chalk::Grammar::BNF::Rule::GrammarRule :isa(Chalk::GrammarRule) {
    method evaluate($context) {
        # Two alternatives:
        # 1. GrammarRule -> Nonterminal WS '->' WS RHS Comment (6 children)
        # 2. GrammarRule -> Nonterminal WS '->' WS RHS (5 children)
        # Children: [0] = LHS nonterminal name (string)
        #           [1] = whitespace (ignore)
        #           [2] = '->' (ignore)
        #           [3] = whitespace (ignore)
        #           [4] = RHS (array of symbols)
        #           [5] = optional inline comment (ignore if present)

        my $children = $context->children();
        my @children = map { $_->extract() } $children->@*;

        # Extract LHS (nonterminal name)
        my $lhs = $children[0];

        # Extract RHS (array of symbols)
        # Inline comment at [5] is automatically ignored (only present in 6-child case)
        my $rhs = $children[4] // [];
        $rhs = [] unless ref($rhs) eq 'ARRAY';

        # Return a Chalk::GrammarRule object directly
        return Chalk::GrammarRule->new(
            lhs         => $lhs,
            rhs         => $rhs,
            probability => 1.0
        );
    }
}

